#!/usr/bin/env bash
# Profile CI's matrix (ADR-0003): every profile in the catalog, each generated by the CLI from the real packs alone,
# so a new profile is run without editing the workflow. Needs a Release build of the CLI.
#
# Writes two lines for $GITHUB_OUTPUT: profiles=["...", ...], every profile, and affected=[...], the profiles a pull
# request's changes can alter. A profile whose packs are not all written gets an ::error:: naming the packs it lacks
# (the slots only those packs declare fail too, and are not repeated), and the script fails once every profile has
# been tried, without writing the lines. A profile that fails to generate with every pack present fails it at once.
#
# --changed names a file listing the changed paths, one per line, relative to the repository. A change to an option's
# pack affects the profiles that select that pack, as a project choice or a module default; a change to docs/,
# tests/ or a Markdown file at the root affects none; any other change, src/, build/, the catalog, a base pack,
# .github/ among them, affects every profile. Without --changed (a push to main), every profile is affected.
# Usage: build/complete-profiles.sh [--changed <file>] >> "$GITHUB_OUTPUT"
set -euo pipefail

changed=""
if [[ $# -gt 0 ]]; then
  [[ $# -eq 2 && $1 == --changed && -f $2 ]] || { echo "Usage: build/complete-profiles.sh [--changed <file of changed paths>]" >&2; exit 2; }
  changed="$2"
fi

repository="$(cd "$(dirname "$0")/.." && pwd)"
cli="$repository/src/Fabric.Cli/bin/Release/net11.0/fabric.dll"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

fabric() { dotnet "$cli" "$@"; }

missing_prefix="error: no pack for "
# Assigned first: a failing command substitution inside the for list would not stop the script.
profiles="$(fabric profiles)"
complete=()
incomplete=0
for profile in $profiles; do
  if errors="$(fabric new "$work/$profile" --name shop --profile "$profile" 2>&1 >/dev/null)"; then
    complete+=("\"$profile\"")
  elif grep --quiet "^$missing_prefix" <<<"$errors"; then
    missing="$(grep "^$missing_prefix" <<<"$errors" | sed -e "s/^$missing_prefix//" -e 's/\.$//' | paste -s -d , - | sed 's/,/, /g')"
    echo "::error title=profile CI::$profile is not complete, its packs are not all written: no pack for $missing." >&2
    incomplete=$((incomplete + 1))
  else
    echo "::error title=profile CI::$profile does not generate:" >&2
    echo "$errors" >&2
    exit 1
  fi
done

[ "$incomplete" -eq 0 ] || exit 1

# The options a generated project selects, one per line (dimension.option), from its fabric.yaml: the project
# choices, the module defaults and each module's own; settings are numbers, not options.
selected() {
  awk '
    /^[^ #]/ { section = $0; sub(/:.*/, "", section) }
    (section == "project" || section == "module-defaults" || section == "modules") && /^ +[a-z0-9.-]+: ./ {
      key = $0; sub(/^ +/, "", key); sub(/: .*/, "", key)
      value = $0; sub(/^[^:]*: /, "", value); gsub(/[][" ]/, "", value)
      count = split(value, options, ",")
      for (i = 1; i <= count; i++) if (options[i] != "") print key "." options[i]
    }
  ' "$1"
}

# The option whose pack holds a changed path under packs/, or nothing when no pack.yaml is above it (a pack the
# change removed, or a file outside any pack).
owning_option() {
  local directory
  directory="$(dirname "$1")"
  while [[ $directory == packs/* ]]; do
    if [[ -f $repository/$directory/pack.yaml ]]; then
      echo "${directory#packs/}" | tr / .
      return
    fi
    directory="$(dirname "$directory")"
  done
}

everything=""
options=()
if [[ -z $changed ]]; then
  everything="no list of changes"
else
  while IFS= read -r path; do
    [[ -n $path ]] || continue
    case "$path" in
      docs/* | tests/*) continue ;;
      */*) ;;
      *.md) continue ;;
    esac
    option=""
    [[ $path != packs/* ]] || option="$(owning_option "$path")"
    if [[ -z $option || $option == base.* ]]; then
      everything="$path changed"
      break
    fi
    options+=("$option")
  done < "$changed"
fi

affected=()
for entry in "${complete[@]}"; do
  profile="${entry//\"/}"
  if [[ -n $everything ]]; then
    affected+=("$entry")
  elif [[ ${#options[@]} -gt 0 ]] && grep --quiet --line-regexp --fixed-strings --file=<(printf '%s\n' "${options[@]}") <(selected "$work/$profile/fabric.yaml"); then
    affected+=("$entry")
  fi
done

if [[ -n $everything ]]; then
  echo "every profile is affected: $everything." >&2
else
  echo "profiles affected by the changed packs (${options[*]:-none}): ${affected[*]:-none}." >&2
fi
echo "profiles=[$(IFS=,; echo "${complete[*]}")]"
echo "affected=[$(IFS=,; echo "${affected[*]}")]"
